import{_ as s,a0 as i,w as r,s as p,ao as d,I as a,x as n,a1 as e,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse(`{"title":"魅族 Pro 5 Ubuntu 版即將發佈 | LCTT x X-CMD","titleTemplate":false,"description":"魅族 Pro 5 Ubuntu 版即將發佈 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"魅族 Pro 5 Ubuntu 版即將發佈 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"魅族 Pro 5 Ubuntu 版即將發佈 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20160218 Meizu PRO 5 Ubuntu Edition Announced and It's a Beast","title":"魅族 Pro 5 Ubuntu 版即將發佈","tag":"201602","desc":""},"relativePath":"201602/20160218 Meizu PRO 5 Ubuntu Edition Announced and It's a Beast.md","filePath":"[post].md"}`),l={name:"201602/20160218 Meizu PRO 5 Ubuntu Edition Announced and It's a Beast.md"};function b(m,t,f,P,T,C){const o=i("Link");return r(),p("div",null,[t[13]||(t[13]=d('<h1 id="魅族-pro-5-ubuntu-版即將發佈" tabindex="-1">魅族 Pro 5 Ubuntu 版即將發佈 <a class="header-anchor" href="#魅族-pro-5-ubuntu-版即將發佈" aria-label="Permalink to “魅族 Pro 5 Ubuntu 版即將發佈”">​</a></h1><p><strong>Canonical 和魅族剛剛透露魅族 Pro 5 Ubuntu 版將在 2016 世界移動大會召開期間開始預售</strong></p><p>自從上次聽到魅族的消息到現在已經很久了，但是看起來 Canonical 和這個中國的硬件廠商之間的合作關係仍然存在。從表面來看，之前魅族的 MX4 Ubuntu 版只是進行了小範圍的發佈，所以只有很少的設備賣出去了。</p><p>我們僅僅希望魅族 Pro 5 Ubuntu 版可以提高供貨量，尤其是因為它是魅族的一款相當新且還提供支持的手機。</p><p>最新的魅族 Pro 5 是第 5 個支持 Ubuntu Touch 的官方設備，2016 年我們可能會看到更多的手機甚至是平板都會預裝這個操作系統。</p><h2 id="魅族-pro-5-ubuntu-版將會非常震撼" tabindex="-1">魅族 Pro 5 Ubuntu 版將會非常震撼 <a class="header-anchor" href="#魅族-pro-5-ubuntu-版將會非常震撼" aria-label="Permalink to “魅族 Pro 5 Ubuntu 版將會非常震撼”">​</a></h2><p>Canonical 宣稱 Pro 5 是目前已發佈了的 Ubuntu 智能手機中最強大的一個，他們説的是對的，但還有一點沒有被提及，即如果不考慮平板，它也是最大的 Ubuntu Touch 設備。魅族 Pro 5 採用了一顆 Exynos 7420 8 核處理器和 5.7 英寸分辨率為 1920x1080 的 AMOLED 屏，配備第三代康寧大猩猩玻璃以及 LPDDR4 內存技術。</p><p>很多人也許會問這個新手機的系統是否可以和桌面版系統一樣，現在看起來真是如此。</p><p>該公司解釋説，“Canonical 一直致力於通過向各種個人設備提供一個統一的自適應平台來重塑個人計算的視覺表現。因此儘管魅族 Pro 5 缺少 MHL 輸出，但它運行的是最新的代碼，這些代碼與新近發佈的平板和其它設備一樣，可提供一種接近傳統桌面的體驗。”</p><p>魅族 Pro 5 最初於 2015 年 9 月發佈，擁有一個 2100 萬像素的後置攝像頭，可以拍攝 30fps 的 2160p 視頻。同時它還帶有一個指紋傳感器和支持快速充電的 3050 mAh 的鋰電池。</p><p>目前這款手機只在中國和歐洲有售，預定將從 2016 年 2 月 22 日至 25 日的世界移動大會期間開始。</p><p><img src="http://i1-news.softpedia-static.com/images/fitted/620x/meizu-pro-5-ubuntu-edition-announced-and-it-s-a-beast-photos-500526-11.jpg" alt=""></p><hr>',13)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://news.softpedia.com/news/meizu-pro-5-ubuntu-edition-announced-and-it-s-a-beast-photos-500526.shtml"},{default:u(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/meizu-pro-5-ubuntu-edition-announced-and-it-s-a-beast-photos-500526.shtml",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=n("作者：",-1)),e(o,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:u(()=>[...t[2]||(t[2]=[n("Silviu Stahie",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),e(o,{href:"https://github.com/osk874"},{default:u(()=>[...t[3]||(t[3]=[n("osk874",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),e(o,{href:"https://github.com/Yuking-net"},{default:u(()=>[...t[4]||(t[4]=[n("Yuking",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),e(o,{href:"https://linux.cn/"},{default:u(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const g=s(l,[["render",b]]);export{x as __pageData,g as default};
